use vstd::prelude::*;

verus! {
    fn arccos(x: Vec<i8>) -> (res: Vec<i8>)
        requires
            // non‐empty
            x.len() > 0,
            // every input in [−1, 1]
            forall |i: int| 0 <= i && i < x.len() as int
                         ==> -1 <= x[i as usize] && x[i as usize] <= 1,
        ensures
            // same length
            res.len() == x.len(),
            // all outputs in [0,3]
            forall |i: int| 0 <= i && i < res.len() as int
                         ==> 0 <= res[i as usize] && res[i as usize] <= 3,
            // mapping −1 ↦ 3
            forall |i: int| 0 <= i && i < res.len() as int
                         && x[i as usize] == -1
                         ==> res[i as usize] == 3,
            // mapping  1 ↦ 0
            forall |i: int| 0 <= i && i < res.len() as int
                         && x[i as usize] == 1
                         ==> res[i as usize] == 0,
    {
        let mut res: Vec<i8> = Vec::new();
        let mut i: usize = 0;
        let n: usize = x.len();
        while i < n
            invariant
                // index bounds
                i <= n,
                // we've pushed exactly i elements so far
                res.len() == i,
                // for all j < i, the mapping properties hold
                forall |j: int| 0 <= j && j < i as int
                             ==> 0 <= res[j as usize] && res[j as usize] <= 3,
                forall |j: int| 0 <= j && j < i as int
                             && x[j as usize] == -1
                             ==> res[j as usize] == 3,
                forall |j: int| 0 <= j && j < i as int
                             && x[j as usize] == 1
                             ==> res[j as usize] == 0,
            decreases n - i
        {
            let xi: i8 = x[i];
            // re‐use the precondition to assert xi is in [−1,1]
            assert(-1 <= xi && xi <= 1);

            if xi == -1 {
                // forced mapping
                res.push(3);
            } else if xi == 1 {
                // forced mapping
                res.push(0);
            } else {
                // xi == 0 → any in [0,3]; we choose 0
                res.push(0);
            }

            i = i + 1;
        }
        res
    }
}

